@app.post("/binomo-login")
async def binomo_login(body: BinomoLoginBody, request: Request, response: Response):
    email = str(body.email or "").strip()
    password = str(body.password or "")
    if not email or not password:
        raise HTTPException(400, "Informe e-mail e senha da Binomo.")

    # Remove somente a sessão Binomo anterior deste navegador, se existir.
    old_token = request.headers.get("X-Binomo-Session", "") or request.cookies.get(BINOMO_SESSION_COOKIE, "")
    old_state = binomo_sessions.pop(old_token, None) if old_token else None
    if old_state:
        _binomo_close_state(old_state)

    app_session = secrets.token_urlsafe(32)
    device_id = str(100000000 + secrets.randbelow(900000000))
    try:
        auth_token, user_id, cookies = await asyncio.wait_for(
            _binomo_login_http(email, password, device_id),
            timeout=max(20.0, BINOMO_FEED_TIMEOUT + 10.0),
        )
    except asyncio.TimeoutError:
        raise HTTPException(504, "A Binomo não respondeu ao login dentro do limite.")
    except Exception as exc:
        # Nunca inclui e-mail, senha ou token no log.
        error_text = str(exc)[:260]
        print(f"[BINOMO LOGIN] falhou: {type(exc).__name__}: {error_text[:220]}", flush=True)
        low = error_text.lower()
        if "blocked_country" in low or "not available for use in your country" in low:
            raise HTTPException(
                451,
                "BINOMO • BLOQUEIO REGIONAL: a própria Binomo recusou o login para este país/região. "
                "Não é falha de senha nem do MEGA IA. O Crypto IDX oficial ficará offline enquanto a Binomo não autorizar o acesso. "
                "O aplicativo não tentará contornar essa restrição."
            )
        raise HTTPException(401, "Não foi possível conectar à Binomo: " + error_text)

    state = {
        "session_id": app_session,
        "email_masked": _mask_email(email),
        "auth_token": auth_token,
        "user_id": user_id,
        "device_id": device_id,
        "cookies": cookies,
        "created_at": time.time(),
        "last_seen": time.time(),
        "ws_connected": False,
        "ws_last_error": "",
        "ws_last_message_at": 0.0,
        "ws_last_tick_at": 0.0,
        "ws_mode": "",
        "ws_stop": threading.Event(),
        "ws_app": None,
        "ws_thread": None,
    }
    binomo_sessions[app_session] = state
    started = _start_binomo_auth_ws(state)

    response.set_cookie(
        BINOMO_SESSION_COOKIE,
        app_session,
        httponly=True,
        secure=True,
        samesite="lax",
        max_age=BINOMO_SESSION_TTL,
        expires=BINOMO_SESSION_TTL,
        path="/",
    )

    # Dá uma pequena janela para o diagnóstico já refletir o primeiro handshake,
    # sem transformar o login em uma espera longa.
    if started:
        await asyncio.sleep(0.6)

    return {
        "authenticated": True,
        "feed_connecting": bool(started),
        "feed_connected": bool(state.get("ws_connected")),
        "message": (
            "Login Binomo aceito. Feed do Crypto IDX conectado."
            if state.get("ws_connected") else
            "Login Binomo aceito. Tentando conectar o feed do Crypto IDX."
            if started else
            "Login Binomo aceito, mas o WebSocket não pôde ser iniciado."
        ),
        "email_masked": state["email_masked"],
        "asset": BINOMO_CRYPTO_IDX_SYMBOL,
        "ric": BINOMO_CRYPTO_IDX_RIC,
        "session_token": app_session,
    }


@app.post("/binomo-logout")
async def binomo_logout(request: Request, response: Response):
    header_token = request.headers.get("X-Binomo-Session", "")
    cookie_token = request.cookies.get(BINOMO_SESSION_COOKIE, "")
    token = header_token if header_token in binomo_sessions else cookie_token
    state = binomo_sessions.pop(token, None)
    _binomo_close_state(state)
    response.delete_cookie(BINOMO_SESSION_COOKIE, path="/")
    return {"authenticated": False, "connected": False, "message": "Binomo desconectada."}


@app.get("/iq-login-ready")
async def iq_login_ready():
    print("[IQ LOGIN] preflight recebido do painel", flush=True)
    return {
        "ok": True,
        "stage": "BACKEND_OK",
        "iqoptionapi_loaded": IQ_Option is not None,
        "version": APP_VERSION,
    }


@app.post("/iq-login")
async def iq_login(body: IQLoginBody, response: Response):
    email = body.email.strip()
    password = body.password
    print(f"[IQ LOGIN] POST recebido dominio={email.split('@')[-1] if '@' in email else 'invalido'}", flush=True)

    if not email or not password:
        raise HTTPException(
            400,
            "Informe e-mail e senha da IQ Option."
        )

    if IQ_Option is None:
        raise HTTPException(
            503,
            "Biblioteca iqoptionapi não carregada no servidor."
        )

    token = secrets.token_urlsafe(32)

    client = None
    last_exc = None

    # _iq_connect_fresh já possui stable_api + fallback interno.
    # Uma única tentativa evita deixar duas conexões presas no Render.
    for attempt in range(1):
        print("[IQ LOGIN] conexão robusta stable_api + fallback", flush=True)
        try:
            client = await asyncio.wait_for(
                asyncio.to_thread(
                    _iq_connect_fresh,
                    email,
                    password,
                ),
                timeout=IQ_CONNECT_TIMEOUT + 8,
            )
            if client is not None:
                break
        except Exception as exc:
            last_exc = exc
            low = str(exc).lower()
            fatal = (
                "senha" in low
                or "credenciais" in low
                or "invalid_credentials" in low
                or "2fa" in low
                or "duas etapas" in low
            )
            if fatal or attempt >= 0:
                break
            await asyncio.sleep(1.5)

    if client is None:
        exc = last_exc or RuntimeError("Falha desconhecida ao conectar.")
        print(f"[IQ LOGIN] falhou: {type(exc).__name__}: {str(exc)[:260]}", flush=True)
        if isinstance(exc, (asyncio.TimeoutError, TimeoutError)):
            raise HTTPException(
                504,
                "A IQ Option não respondeu dentro do limite. O MEGA IA encerrou a tentativa sem criar conexão duplicada. Tente novamente; se persistir, o servidor Render pode não estar conseguindo manter o WebSocket da corretora."
            )
        raise HTTPException(
            401,
            "Não foi possível conectar à IQ Option: "
            + str(exc)[:280]
        )

    print("[IQ LOGIN] conectado com sucesso", flush=True)

    state = {
        "session_id": token,
        "email": email,
        "password": password,
        "client": client,
        "lock": asyncio.Lock(),
        "sync_lock": threading.RLock(),
        "connected": True,
        "reconnecting": False,
        "failure_count": 0,
        "reconnect_after": 0.0,
        "last_attempt": time.time(),
        "last_seen": time.time(),
        "last_connected": time.time(),
        "last_error": "",
        "candle_cache": {},
        "results": {},
        "auto_orders": {},
        "auto_account": "PRACTICE",
        "otc_recent_available": {},
        "otc_open_pairs_cache": {},
        "order_lock": asyncio.Lock(),
    }
    iq_sessions[token] = state

    response.set_cookie(
        IQ_SESSION_COOKIE,
        token,
        httponly=True,
        secure=True,
        samesite="lax",
        max_age=IQ_SESSION_TTL,
        expires=IQ_SESSION_TTL,
        path="/",
    )

    return {
        "connected": True,
        "message": "IQ Option conectada.",
        "email_masked": _mask_email(email),
        "session_token": token,
    }



def _iq_parse_buy_result(result):
    if isinstance(result, (tuple, list)):
        ok = bool(result[0]) if result else False
        order_id = result[1] if len(result) > 1 else None
        return ok, order_id
    if isinstance(result, bool):
        return result, None
    if result is None:
        return False, None
    return True, result


def _iq_auto_candidates(symbol: str, market: str):
    """Nomes que podem ser enviados para a IQ, sem misturar OPEN e OTC."""
    market = str(market or "OPEN").upper()
    if market == "IQ_OTC":
        # Nunca cai silenciosamente para o ativo normal quando o usuário pediu OTC.
        return [c for c in iq_active_candidates(symbol) if "OTC" in _iq_active_norm(c)]
    return [c for c in iq_regular_active_candidates(symbol) if "OTC" not in _iq_active_norm(c)]


def _iq_auto_open_books_blocking(state: Dict[str, Any]):
    """Obtém os ativos realmente abertos para turbo/binary/digital, com cache curto."""
    now_ts = time.time()
    cached = state.get("auto_open_time_cache") if state else None
    if isinstance(cached, dict) and now_ts - float(cached.get("ts", 0) or 0) < 12:
        return cached

    client = state.get("client") if state else None
    getter = getattr(client, "get_all_open_time", None) if client is not None else None
    if not callable(getter):
        result = {"ts": now_ts, "exact": False, "books": {}, "error": "get_all_open_time indisponível"}
        if state is not None:
            state["auto_open_time_cache"] = result
        return result

    try:
        sync_lock = state.get("sync_lock")
        if sync_lock is None:
            sync_lock = threading.RLock()
            state["sync_lock"] = sync_lock
        with sync_lock:
            raw = getter()
        books = {}
        if isinstance(raw, dict):
            for book_name in ("turbo", "binary", "digital"):
                book = raw.get(book_name) or {}
                if not isinstance(book, dict):
                    continue
                opened = {}
                for active_name, info in book.items():
                    if isinstance(info, dict) and bool(info.get("open")):
                        opened[_iq_active_norm(active_name)] = str(active_name)
                books[book_name] = opened
        result = {"ts": now_ts, "exact": bool(books), "books": books, "error": ""}
    except Exception as exc:
        result = {"ts": now_ts, "exact": False, "books": {}, "error": str(exc)[:180]}

    state["auto_open_time_cache"] = result
    return result


def _iq_auto_capability_blocking(state: Dict[str, Any], symbol: str, interval: str, market: str):
    client = _iq_reconnect_state(state)
    if not _iq_connected(state):
        return {"available": False, "reason": "IQ Option desconectada.", "methods": []}

    expiry_minutes = max(1, int(round(iq_seconds(interval) / 60)))
    candidates = _iq_auto_candidates(symbol, market)
    snap = _iq_auto_open_books_blocking(state)
    books = snap.get("books") or {}
    methods = []
    actives = []

    for book_name in (("turbo", "binary") if expiry_minutes <= 5 else ("binary", "turbo")):
        book = books.get(book_name) or {}
        for candidate in candidates:
            matched = book.get(_iq_active_norm(candidate))
            if matched:
                methods.append(book_name.upper())
                actives.append(matched)
                break

    if expiry_minutes in (1, 5):
        book = books.get("digital") or {}
        for candidate in candidates:
            matched = book.get(_iq_active_norm(candidate))
            if matched:
                methods.append("DIGITAL")
                actives.append(matched)
                break

    methods = list(dict.fromkeys(methods))
    actives = list(dict.fromkeys(actives))
    if snap.get("exact"):
        return {
            "available": bool(methods),
            "reason": ("Disponível: " + ", ".join(methods)) if methods else "Ativo fechado/indisponível para opções na IQ Option.",
            "methods": methods,
            "actives": actives,
            "exact": True,
        }

    # Se o fork não conseguiu listar abertura, permitimos a tentativa controlada
    # e deixamos a própria IQ responder; assim uma falha do catálogo não trava o robô.
    return {
        "available": True,
        "reason": "Não foi possível validar o catálogo; a ordem fará tentativa controlada.",
        "methods": [],
        "actives": candidates,
        "exact": False,
        "catalog_error": snap.get("error", ""),
    }


def _iq_place_demo_order_blocking(state: Dict[str, Any], symbol: str, interval: str, direction: str, amount: float, market: str):
    client = _iq_reconnect_state(state)
    if not _iq_connected(state):
        raise RuntimeError("IQ Option desconectada.")

    changer = getattr(client, "change_balance", None)
    if callable(changer):
        changed = changer("PRACTICE")
        if changed is False:
            raise RuntimeError("Não foi possível selecionar a conta DEMO/PRACTICE.")

    action = "call" if direction == "CALL" else "put"
    expiry_minutes = max(1, int(round(iq_seconds(interval) / 60)))
    candidates = _iq_auto_candidates(symbol, market)
    if not candidates:
        raise RuntimeError("Ativo sem mapeamento válido para este mercado da IQ Option.")

    snap = _iq_auto_open_books_blocking(state)
    books = snap.get("books") or {}
    exact = bool(snap.get("exact"))
    errors = []
    attempted = set()

    def finish(order_id, active, order_type, book_name):
        state["connected"] = True
        state["last_seen"] = time.time()
        state["last_error"] = ""
        return {
            "ok": True,
            "order_id": str(order_id) if order_id is not None else "",
            "active": active,
            "action": action,
            "amount": round(float(amount), 2),
            "expiry_minutes": expiry_minutes,
            "account": "PRACTICE",
            "order_type": order_type,
            "market_book": book_name,
        }

    def try_binary(active, book_name="turbo"):
        buyer = getattr(client, "buy", None)
        if not callable(buyer):
            errors.append("BINARY: função buy() indisponível")
            return None
        tag = ("BINARY", active)
        if tag in attempted:
            return None
        attempted.add(tag)
        try:
            result = buyer(float(amount), active, action, expiry_minutes)
            ok, order_id = _iq_parse_buy_result(result)
            if ok:
                return finish(order_id, active, "BINARY", book_name.upper())
            detail = str(order_id) if order_id not in (None, "") else "ordem recusada"
            errors.append(f"{book_name.upper()} {active}: {detail}")
        except Exception as exc:
            errors.append(f"{book_name.upper()} {active}: {str(exc) or exc.__class__.__name__}")
        return None

    def try_digital(active):
        if expiry_minutes not in (1, 5):
            return None
        tag = ("DIGITAL", active)
        if tag in attempted:
            return None
        attempted.add(tag)
        methods = [
            ("buy_digital_spot_v2", getattr(client, "buy_digital_spot_v2", None)),
            ("buy_digital_spot", getattr(client, "buy_digital_spot", None)),
        ]
        available_method = False
        for method_name, method in methods:
            if not callable(method):
                continue
            available_method = True
            try:
                result = method(active, float(amount), action, expiry_minutes)
                ok, order_id = _iq_parse_buy_result(result)
                if ok:
                    return finish(order_id, active, "DIGITAL", method_name.upper())
                detail = str(order_id) if order_id not in (None, "") else "ordem recusada"
                errors.append(f"DIGITAL {active}/{method_name}: {detail}")
            except Exception as exc:
                errors.append(f"DIGITAL {active}/{method_name}: {str(exc) or exc.__class__.__name__}")
        if not available_method:
            errors.append("DIGITAL: método de compra indisponível nesta iqoptionapi")
        return None

    # 1) Quando o catálogo está disponível, usamos SOMENTE ativos realmente abertos.
    if exact:
        binary_books = ("turbo", "binary") if expiry_minutes <= 5 else ("binary", "turbo")
        for book_name in binary_books:
            book = books.get(book_name) or {}
            for candidate in candidates:
                active = book.get(_iq_active_norm(candidate))
                if active:
                    placed = try_binary(active, book_name)
                    if placed:
                        return placed
                    break

        if expiry_minutes in (1, 5):
            digital_book = books.get("digital") or {}
            for candidate in candidates:
                active = digital_book.get(_iq_active_norm(candidate))
                if active:
                    placed = try_digital(active)
                    if placed:
                        return placed
                    break

        if not attempted:
            raise RuntimeError(
                f"{symbol} não está aberto agora em TURBO/BINARY/DIGITAL na IQ Option para {interval}."
            )

    # 2) Se o catálogo do fork falhou, mantém compatibilidade: tenta os nomes conhecidos,
    #    primeiro binária/turbo e depois digital (M1/M5).
    else:
        for active in candidates:
            placed = try_binary(active, "fallback")
            if placed:
                return placed
        if expiry_minutes in (1, 5):
            for active in candidates:
                placed = try_digital(active)
                if placed:
                    return placed

    detail = " | ".join(errors[-5:])[:520]
    raise RuntimeError("IQ Option recusou a ordem DEMO. " + (detail or "Nenhum método de opções disponível para este ativo."))


@app.post("/iq-auto-order")
async def iq_auto_order(body: IQAutoOrderBody, request: Request):
    state = _iq_session_state(request, required=True)

    symbol = str(body.symbol or "").upper()
    interval = str(body.interval or "1min")
    direction = str(body.direction or "").upper()
    market = str(body.market or "OPEN").upper()
    amount = float(body.amount or 0)
    stage = str(body.stage or "ENTRADA").upper()

    if symbol not in SYMBOLS:
        raise HTTPException(400, "Ativo inválido para AUTO ENTRADA.")
    if interval not in INTERVALS:
        raise HTTPException(400, "Intervalo inválido para AUTO ENTRADA.")
    if direction not in ("CALL", "PUT"):
        raise HTTPException(400, "Direção inválida para AUTO ENTRADA.")
    if market not in VALID_MARKETS:
        raise HTTPException(400, "Mercado inválido para AUTO ENTRADA.")
    if amount < 1 or amount > 1000:
        raise HTTPException(400, "No teste DEMO, use valor entre 1 e 1000 por entrada.")
    if stage not in ("ENTRADA", "G1", "G2"):
        raise HTTPException(400, "Etapa inválida para AUTO ENTRADA.")

    try:
        entry_dt = parse_dt(body.entry_time)
    except Exception:
        raise HTTPException(400, "Horário de entrada inválido.")

    delta = (now() - entry_dt).total_seconds()
    if delta < -8:
        raise HTTPException(409, f"A entrada ainda não abriu. Faltam aproximadamente {int(abs(delta))}s.")
    if delta > 20:
        raise HTTPException(409, "Janela da entrada automática encerrada para este sinal.")

    order_key = "|".join([
        market,
        symbol,
        interval,
        direction,
        _canonical_time_key(body.entry_time),
        stage,
        "PRACTICE",
    ])

    order_lock = state.get("order_lock")
    if order_lock is None:
        order_lock = asyncio.Lock()
        state["order_lock"] = order_lock

    async with order_lock:
        store = state.setdefault("auto_orders", {})
        previous = store.get(order_key)
        if previous:
            prev_status = str(previous.get("status") or "").upper()
            if prev_status == "PLACED":
                return {**previous, "duplicate": True}
            if prev_status == "UNKNOWN_TIMEOUT":
                raise HTTPException(409, "A tentativa anterior ficou sem confirmação. Não será reenviada para evitar ordem duplicada.")
            # REJECTED/PLACING antigo não é tratado como sucesso. Libera nova tentativa.
            store.pop(order_key, None)

        store[order_key] = {
            "ok": False,
            "status": "PLACING",
            "order_key": order_key,
            "account": "PRACTICE",
            "created_at": iso(now()),
        }

        try:
            placed = await asyncio.wait_for(
                asyncio.to_thread(
                    _iq_place_demo_order_blocking,
                    state,
                    symbol,
                    interval,
                    direction,
                    amount,
                    market,
                ),
                timeout=24,
            )
        except asyncio.TimeoutError:
            # Mantém a chave bloqueada: em timeout não repetimos, pois a corretora
            # pode ter recebido a ordem mesmo sem a resposta voltar a tempo.
            store[order_key] = {
                "ok": False,
                "status": "UNKNOWN_TIMEOUT",
                "order_key": order_key,
                "account": "PRACTICE",
                "created_at": iso(now()),
                "message": "Tempo excedido. A ordem não será reenviada automaticamente para evitar duplicidade.",
            }
            raise HTTPException(504, store[order_key]["message"])
        except Exception as exc:
            store[order_key] = {
                "ok": False,
                "status": "REJECTED",
                "order_key": order_key,
                "account": "PRACTICE",
                "created_at": iso(now()),
                "message": str(exc)[:350],
            }
            raise HTTPException(502, str(exc)[:350])

        result = {
            **placed,
            "status": "PLACED",
            "order_key": order_key,
            "symbol": symbol,
            "interval": interval,
            "direction": direction,
            "market": market,
            "entry_time": iso(entry_dt),
            "stage": stage,
            "created_at": iso(now()),
            "duplicate": False,
        }
        store[order_key] = result

        # Limita memória da sessão sem perder os pedidos mais recentes.
        if len(store) > 120:
            for old_key in list(store.keys())[:-100]:
                store.pop(old_key, None)

        return result


def _iq_auto_order_result_snapshot(state: Dict[str, Any], order_id: str):
    """Lê o resultado já fechado da ordem DEMO sem bloquear a thread.

    A iqoptionapi publica as opções encerradas em ``api.socket_option_closed``.
    Se a versão instalada não expuser esse mapa, devolvemos PENDENTE e o painel
    usa o resultado da vela como fallback para decidir o Gale.
    """
    client = state.get("client") if state else None
    api = getattr(client, "api", None) if client is not None else None
    closed = getattr(api, "socket_option_closed", None) if api is not None else None
    if not isinstance(closed, dict):
        return {"settled": False, "result": None, "message": "Resultado da ordem ainda indisponível."}

    keys = [order_id, str(order_id)]
    try:
        keys.append(int(float(str(order_id))))
    except Exception:
        pass

    payload = None
    for k in keys:
        try:
            if k in closed and closed.get(k):
                payload = closed.get(k)
                break
        except Exception:
            continue

    if not isinstance(payload, dict):
        return {"settled": False, "result": None}

    win_raw = str(payload.get("win") or payload.get("result") or "").strip().lower()
    amount = payload.get("amount", 0)
    win_amount = payload.get("win_amount", payload.get("profit_amount", 0))
    try:
        amount = float(amount or 0)
    except Exception:
        amount = 0.0
    try:
        win_amount = float(win_amount or 0)
    except Exception:
        win_amount = 0.0

    if win_raw in ("win", "won"):
        profit = win_amount - amount if win_amount else None
        return {"settled": True, "result": "WIN", "profit": profit, "order_id": str(order_id)}
    if win_raw in ("equal", "draw", "tie"):
        return {"settled": True, "result": "DRAW", "profit": 0.0, "order_id": str(order_id)}
    if win_raw in ("loose", "loss", "lose", "lost"):
        return {"settled": True, "result": "LOSS", "profit": -abs(amount) if amount else None, "order_id": str(order_id)}

    return {"settled": False, "result": None}


@app.post("/iq-auto-order-result")
async def iq_auto_order_result(body: IQAutoOrderResultBody, request: Request):
    state = _iq_session_state(request, required=True)
    order_id = str(body.order_id or "").strip()
    if not order_id:
        raise HTTPException(400, "order_id é obrigatório.")
    return _iq_auto_order_result_snapshot(state, order_id)


@app.get("/iq-auto-status")
async def iq_auto_status(request: Request):
    state = _iq_session_state(request, required=False)
    if not state:
        return {"connected": False, "account": "PRACTICE", "orders": []}
    orders = list(state.get("auto_orders", {}).values())[-20:]
    return {
        "connected": _iq_connected(state),
        "account": "PRACTICE",
        "orders": orders,
    }


@app.get("/iq-auto-capability")
async def iq_auto_capability(request: Request, symbol: str = "EUR/USD", interval: str = "1min", market: str = "OPEN"):
    state = _iq_session_state(request, required=False)
    if not state or not _iq_connected(state):
        return {"connected": False, "available": False, "reason": "Conecte a IQ Option primeiro.", "methods": []}

    symbol = str(symbol or "").upper()
    interval = str(interval or "1min")
    market = str(market or "OPEN").upper()
    if interval not in INTERVALS:
        raise HTTPException(400, "Intervalo inválido.")
    if market not in VALID_MARKETS:
        raise HTTPException(400, "Mercado inválido.")
    if symbol == BINOMO_CRYPTO_IDX_SYMBOL:
        return {"connected": True, "available": False, "reason": "Crypto IDX não é um ativo de opções da IQ Option.", "methods": []}

    try:
        data = await asyncio.wait_for(
            asyncio.to_thread(_iq_auto_capability_blocking, state, symbol, interval, market),
            timeout=12,
        )
    except asyncio.TimeoutError:
        data = {"available": True, "reason": "Catálogo da IQ demorou; a ordem fará tentativa controlada.", "methods": [], "exact": False}
    return {"connected": True, "symbol": symbol, "interval": interval, "market": market, **data}


@app.post("/iq-logout")
async def iq_logout(
    request: Request,
    response: Response,
):
    header_token = request.headers.get(
        "X-IQ-Session",
        "",
    )
    cookie_token = request.cookies.get(
        IQ_SESSION_COOKIE,
        "",
    )

    token = (
        header_token
        if header_token in iq_sessions
        else cookie_token
    )

    state = iq_sessions.pop(token, None)

    if state:
        state["password"] = ""
        state["candle_cache"] = {}
        _iq_close_state(state)

    response.delete_cookie(
        IQ_SESSION_COOKIE,
        path="/",
    )

    return {
        "connected": False,
        "message": "IQ Option desconectada.",
    }




@app.get("/otc-status")
async def otc_status(request: Request, broker: str = "IQ_OPTION"):
    broker = (broker or "IQ_OPTION").upper()

    state = _iq_session_state(
        request,
        required=False,
    )
    connected = _iq_connected(state)

    return {
        "broker": "IQ_OPTION",
        "configured": IQ_Option is not None,
        "connected": connected,
        "message": (
            "IQ Option conectada pelo painel."
            if connected
            else (
                "Faça login com e-mail e senha na aba Corretora."
                if IQ_Option is not None
                else "Biblioteca iqoptionapi não carregada no servidor."
            )
        ),
        "pairs": len(OTC_BASE),
    }


@app.get("/otc-active-pairs")
async def otc_active_pairs(request: Request):
    """Retorna somente os pares OTC que estão disponíveis na sessão IQ agora."""
    state = _iq_session_state(request, required=False)
    if not state or not _iq_connected(state):
        return {
            "ok": True,
            "connected": False,
            "pairs": [],
            "count": 0,
            "status": "IQ OPTION OFFLINE",
            "message": "Conecte sua conta da IQ Option para consultar os ativos OTC abertos.",
        }

    try:
        info = await asyncio.wait_for(
            asyncio.to_thread(_iq_otc_open_pairs_blocking, state),
            timeout=8,
        )
    except Exception as exc:
        info = {
            "pairs": [],
            "source": "ERROR",
            "exact": False,
            "error": str(exc)[:180],
        }

    pairs = [s for s in info.get("pairs", []) if s in SYMBOLS]

    # Se o fork não informa open_time, o radar vai construindo a lista com
    # candles OTC recentes. Faz um probe leve de um ativo por chamada, sem
    # consultar todos ao mesmo tempo.
    if not info.get("exact"):
        idx_key = "OTC_ACTIVE_PROBE_INDEX"
        idx = int(state.get(idx_key, 0) or 0) % len(OTC_SYMBOLS)
        probe_symbol = OTC_SYMBOLS[idx]
        state[idx_key] = (idx + 1) % len(OTC_SYMBOLS)
        try:
            await candles(probe_symbol, "1min", 30, "IQ_OTC", state, request=request)
            state.setdefault("otc_recent_available", {})[probe_symbol] = time.time()
        except Exception:
            pass
        recent = state.get("otc_recent_available") or {}
        pairs = [s for s in OTC_SYMBOLS if time.time() - float(recent.get(s, 0) or 0) <= 90]

    return {
        "ok": True,
        "connected": True,
        "pairs": pairs,
        "count": len(pairs),
        "status": "OTC ATIVOS" if pairs else "NENHUM OTC ABERTO DETECTADO",
        "source": info.get("source", "UNKNOWN"),
        "exact": bool(info.get("exact")),
        "message": (
            f"{len(pairs)} ativo(s) OTC disponível(is) agora."
            if pairs else
            "Nenhum ativo OTC aberto foi detectado neste momento."
        ),
    }



def _compat_dt(value):
    """Normaliza o horário do candle para comparação, preservando ajuste de fuso separado."""
    if isinstance(value, datetime):
        dt = value
    else:
        raw = str(value or "").strip()
        if not raw:
            return None
        try:
            dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except Exception:
            for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
                try:
                    dt = datetime.strptime(raw, fmt)
                    break
                except Exception:
                    dt = None
            if dt is None:
                return None

    if dt.tzinfo is not None:
        dt = dt.astimezone(BR_TZ).replace(tzinfo=None)
    return dt.replace(second=0, microsecond=0)


def _compat_direction(candle):
    try:
        o = float(candle.get("open"))
        c = float(candle.get("close"))
    except Exception:
        return "UNKNOWN"
    eps = max(abs(o) * 1e-9, 1e-12)
    if c > o + eps:
        return "UP"
    if c < o - eps:
        return "DOWN"
    return "DOJI"


def _compare_candle_feeds(app_rows, broker_rows, sample=50):
    """Compara fechamento/horário/direção de duas fontes sem alterar a estratégia de sinais."""
    app_rows = list(app_rows or [])[-max(10, int(sample)):]
    broker_rows = list(broker_rows or [])[-max(10, int(sample)):]

    app_parsed = []
    for row in app_rows:
        dt = _compat_dt(row.get("datetime") if isinstance(row, dict) else None)
        if dt:
            app_parsed.append((dt, row))

    broker_parsed = []
    for row in broker_rows:
        dt = _compat_dt(row.get("datetime") if isinstance(row, dict) else None)
        if dt:
            broker_parsed.append((dt, row))

    base = max(1, min(len(app_parsed), len(broker_parsed), max(10, int(sample))))
    broker_map = {dt: row for dt, row in broker_parsed}

    # Twelve Data pode rotular o horário em outro fuso. Procuramos o melhor ajuste
    # de horas, mas qualquer deslocamento residual de minuto é tratado como alerta.
    best = None
    for hour_shift in range(-12, 15):
        for minute_shift in (-2, -1, 0, 1, 2):
            shift = timedelta(hours=hour_shift, minutes=minute_shift)
            pairs = []
            for dt, row in app_parsed:
                other = broker_map.get(dt + shift)
                if other is not None:
                    pairs.append((row, other))
            score = (len(pairs), 1 if minute_shift == 0 else 0, -abs(hour_shift), -abs(minute_shift))
            if best is None or score > best[0]:
                best = (score, hour_shift, minute_shift, pairs)

    _, hour_shift, minute_shift, pairs = best if best else ((0, 0, 0, 0), 0, 0, [])
    matched = len(pairs)
    time_match = round((matched / base) * 100.0, 2) if base else 0.0

    direction_hits = 0
    valid_direction = 0
    close_diffs = []
    examples = []
    for app_c, broker_c in pairs:
        ad = _compat_direction(app_c)
        bd = _compat_direction(broker_c)
        if ad != "UNKNOWN" and bd != "UNKNOWN":
            valid_direction += 1
            if ad == bd:
                direction_hits += 1
        try:
            ac = float(app_c.get("close"))
            bc = float(broker_c.get("close"))
            denom = max(abs(ac), abs(bc), 1e-12)
            close_diffs.append(abs(ac - bc) / denom * 100.0)
        except Exception:
            pass
        if len(examples) < 5:
            examples.append({
                "app_direction": ad,
                "broker_direction": bd,
                "app_close": app_c.get("close"),
                "broker_close": broker_c.get("close"),
            })

    direction_match = round((direction_hits / valid_direction) * 100.0, 2) if valid_direction else 0.0
    avg_close_diff = round(sum(close_diffs) / len(close_diffs), 5) if close_diffs else None

    if matched < min(20, base):
        verdict = "AMOSTRA INSUFICIENTE"
        grade = "WAITING"
    elif minute_shift != 0:
        verdict = "ATENÇÃO AO FECHAMENTO"
        grade = "WARNING"
    elif time_match >= 95 and direction_match >= 96:
        verdict = "MUITO COMPATÍVEL"
        grade = "EXCELLENT"
    elif time_match >= 90 and direction_match >= 90:
        verdict = "COMPATÍVEL"
        grade = "GOOD"
    elif time_match >= 80 and direction_match >= 80:
        verdict = "ATENÇÃO"
        grade = "WARNING"
    else:
        verdict = "NÃO RECOMENDADA PARA M1"
        grade = "BAD"

    return {
        "sample_requested": int(sample),
        "app_candles": len(app_parsed),
        "broker_candles": len(broker_parsed),
        "matched_candles": matched,
        "time_match_percent": time_match,
        "direction_match_percent": direction_match,
        "average_close_difference_percent": avg_close_diff,
        "detected_hour_shift": hour_shift,
        "detected_minute_shift": minute_shift,
        "verdict": verdict,
        "grade": grade,
        "examples": examples,
    }


@app.get("/compatibility-test")
async def compatibility_test(
    request: Request,
    symbol: str = "EUR/USD",
    interval: str = "1min",
    sample: int = 50,
    broker: str = "IQ_OPTION",
):
    """Compara o feed OPEN do MEGA IA com o mercado aberto da corretora conectada."""
    symbol = str(symbol or "EUR/USD").upper()
    interval = str(interval or "1min")
    broker = str(broker or "IQ_OPTION").upper()
    sample = max(20, min(int(sample or 50), 100))

    if symbol not in SYMBOLS or interval not in INTERVALS:
        raise HTTPException(400, "Ativo ou intervalo inválido.")
    if broker != "IQ_OPTION":
        raise HTTPException(400, "Esta versão mede automaticamente apenas a IQ Option.")

    iq_state = _iq_session_state(request, required=False)
    if not iq_state or not _iq_connected(iq_state):
        return {
            "ok": False,
            "broker": "IQ Option",
            "symbol": symbol,
            "interval": interval,
            "status": "CORRETORA DESCONECTADA",
            "message": "Conecte a IQ Option na aba Corretora para comparar as velas do mercado aberto.",
        }

    # Pede uma margem extra e remove a vela em formação dos dois lados.
    need = min(120, sample + 8)
    try:
        app_rows = await candles_open(symbol, interval, need, request=request)
    except Exception as exc:
        return {
            "ok": False,
            "broker": "IQ Option",
            "symbol": symbol,
            "interval": interval,
            "status": "FONTE DO APP INDISPONÍVEL",
            "message": str(exc)[:220],
        }

    try:
        lock = iq_state.get("lock") or asyncio.Lock()
        iq_state["lock"] = lock
        async with lock:
            broker_rows = await asyncio.wait_for(
                asyncio.to_thread(
                    iq_candles_blocking,
                    iq_state,
                    symbol,
                    interval,
                    need,
                    True,
                ),
                timeout=IQ_CANDLE_TIMEOUT + 5,
            )
    except Exception as exc:
        return {
            "ok": False,
            "broker": "IQ Option",
            "symbol": symbol,
            "interval": interval,
            "status": "CANDLES DA CORRETORA INDISPONÍVEIS",
            "message": str(exc)[:220],
        }

    app_closed = app_rows[:-1] if len(app_rows) > 1 else app_rows
    broker_closed = broker_rows[:-1] if len(broker_rows) > 1 else broker_rows
    metrics = _compare_candle_feeds(app_closed, broker_closed, sample)

    return {
        "ok": True,
        "broker": "IQ Option",
        "source": "MEGA IA • Mercado Aberto",
        "symbol": symbol,
        "interval": interval,
        "tested_at": iso(now()),
        **metrics,
        "note": "Teste técnico dos candles. Não é garantia de resultado financeiro e não valida OTC.",
    }


